function sci(n,d=3){if(!Number.isFinite(n))return'—';if(n===0)return'0';if(Math.abs(n)>=1e5||Math.abs(n)<.001)return n.toExponential(d).replace('e+',' ×10^').replace('e-',' ×10^-');return nf(n,d);}
