function controls(){
 $('params').innerHTML=experiments[current].params.filter(q=>!q.gridOnly||['cube','geometry'].includes(view)).filter(q=>!q.disk||view==='disk').filter(q=>current!=='clocks'||(q.key!=='ratio'||p.mode==='scaled')&&(q.key!=='distance'||p.mode==='absolute')&&(q.key!=='heightPreset'||p.mode==='height')).map(q=>{
 let input;if(q.type==='select'||q.type==='planet'){const opts=q.type==='planet'?planets.map(b=>[b.id,b.uk,b.en]):q.options;input=`<select id="p-${q.key}" data-key="${q.key}">${opts.map(o=>`<option value="${o[0]}" ${String(p[q.key])===o[0]?'selected':''}>${o[lang==='uk'?1:2]}</option>`).join('')}</select>`;}else input=`<input id="p-${q.key}" data-key="${q.key}" type="${q.type}" min="${q.min}" max="${q.max}" step="${q.step}" value="${p[q.key]}" aria-valuetext="${p[q.key]} ${q.units}">${q.type==='range'?`<div class="extents"><span>${q.min} ${q.units}</span><span>${q.max} ${q.units}</span></div>`:''}`;
 return `<div class="parameter"><div class="param-head"><label for="p-${q.key}">${tr(q.labels,lang)}</label><output id="o-${q.key}">${q.type==='range'?nf(p[q.key],3)+' '+q.units:q.units}</output></div>${input}</div>`;
 }).join('');$('renderBtn').hidden=view!=='disk';$('seriesBtn').title=T(current==='clocks'&&p.mode==='height'?'heightSeriesNote':'seriesNote');
}
