function staticContent(){const e=experiments[current];$('modelBadge').textContent=tr(e.badge,lang);$('labTitle').textContent=name(current);$('labSubtitle').textContent=tr(e.tag,lang);$('theoryContent').innerHTML=theory(current,lang);$('sourceList').innerHTML=`<ul>${sources.map(([label,url])=>`<li><a href="${url}" target="_blank" rel="noopener">${label}</a></li>`).join('')}</ul><p>${lang==='uk'?'Прийнято M(Sgr A*) = 4,297 × 10⁶ M☉; для TON 618 — історичну модельно-залежну оцінку log₁₀(M/M☉) = 10,82. TON 618 не позначається як доведено найбільша чорна діра. Планетні радіуси — середні, обертання не враховане.':'Adopted M(Sgr A*) = 4.297 × 10⁶ M☉; for TON 618, the historical model-dependent estimate log₁₀(M/M☉) = 10.82. TON 618 is not labelled definitively the largest black hole. Planet radii are mean radii; rotation is excluded.'}</p>`;
 const steps={surface:[['Порівняй людину й автомобіль на тій самій висоті. Чому сила змінюється, а g — ні?','Compare a person and a car at the same height. Why does force change while g does not?'],['Задай висоту 100 м і ввімкни вільне падіння. Порівняй силу тяжіння, реакцію опори й прискорення.','Set 100 m height and choose free fall. Compare gravity, support force and acceleration.'],['Запиши серію за висотою та побудуй графік g(r). Перевір закон 1/r².','Record a height series, plot g(r), and verify the inverse-square law.']],binary:[['Задай рівні маси та кругову швидкість. Перевір положення барицентра.','Set equal masses and circular speed. Check the barycentre.'],['Подвой відстань за незмінних мас. Порівняй силу та період.','Double separation at fixed masses. Compare force and period.'],['Зменш швидкість до 0,8 кругової; поверни орбітальну площину. Запиши (x, y, z, t).','Reduce speed to 0.8 circular; tilt the orbital plane. Record (x, y, z, t).']],jump:[['Залиши масу 50 кг та земний стрибок 0,5 м. Передбач найвищий стрибок.','Keep mass at 50 kg and the reference Earth jump at 0.5 m. Predict the highest jump.'],['Порівняй рух і час польоту. Зміни масу, зберігши ту саму початкову швидкість.','Compare flight height and duration. Change mass while retaining launch speed.'],['Запиши серію для восьми планет і побудуй h(g). Вручну перевір h = v₀²/(2g).','Record all eight planets and plot h(g). Check h = v₀²/(2g) by hand.']],pn:[['Почни з r₀ = 250r_g та v₀ = 0,85v_circ. Порівняй кольорову й сіру орбіти.','Start at r₀ = 250r_g and v₀ = 0.85v_circ. Compare coloured and grey orbits.'],['Збільш r₀: чи слабшає релятивістська прецесія? Стеж за параметром 1PN.','Increase r₀: does relativistic precession weaken? Watch the 1PN parameter.'],['Зміни співвідношення мас. Порівняй релятивістський центр мас і центроїд мас спокою.','Change the mass ratio. Compare the relativistic CM with the rest-mass centroid.']],schwarzschild:[['Задай r₀ = 10r_g, поперечну швидкість 1 та радіальну 0. Перевір кругову орбіту.','Set r₀ = 10r_g, transverse speed 1 and radial speed 0. Verify a circular orbit.'],['Зменш поперечну швидкість. Спостерігай прецесію або падіння; порівняй t і τ.','Reduce transverse speed. Observe precession or infall; compare t and τ.'],['Зміни масу чорної діри за того самого r/r_g. Порівняй фізичні довжини, часи й кривину.','Change black-hole mass at fixed r/r_g. Compare physical lengths, times and curvature.']],lens:[['Змінюй прицільний параметр b та простеж, як світло огинає чорну діру.','Vary the impact parameter b and follow light bending around the black hole.'],['Порівняй b = 5r_g та b = 7r_g: який промінь захоплюється, а який виходить назовні?','Compare b = 5r_g and b = 7r_g: which ray is captured and which escapes?'],['Запиши серію та побудуй кут відхилення залежно від b. Порівняй із наближенням 4r_g/b.','Record a series and plot deflection against b. Compare with the approximation 4r_g/b.']],clocks:[['Обери висоти 100, 200 і 500 км. Для планет і Сонця це висота над поверхнею, для чорних дір — над горизонтом. Порівняй темп і відставання за добу.','Select 100, 200 and 500 km. For planets and the Sun, height starts at the surface; for black holes, at the horizon. Compare rates and one-day deficits.'],['Порівняй висоти 1, 5, 10, 100 і 1000 а. о. Натисни «Записати серію», щоб зберегти всі 32 результати; у журналі обери height_m і lost_s для осей графіка.','Compare heights of 1, 5, 10, 100 and 1000 AU. Select “Record a series” to save all 32 results; choose height_m and lost_s for the plot axes in the notebook.'],['Зміни висоту окремого годинника в таблиці. Додатково порівняй режими однакового радіуса від центра та однакового r/r_s. Експортуй журнал у CSV.','Edit an individual clock height in the table. Also compare equal centre-based radius and equal r/r_s modes. Export the notebook as CSV.']]};$('procedure').innerHTML=steps[current].map(s=>`<li>${tr(s,lang)}</li>`).join('');
}
function select(id,values=null){cancelDisk();pageMode='lab';current=id;globalThis.history?.replaceState(null,'','?experiment='+id+'&lang='+lang);p={...defaultParams(id),...(values||{})};clockOverrides={};clockHeightOverrides={};view=id==='clocks'?'geometry':experiments[id].category==='gr'?'cube':'scene';cube.mode='deform';cube.gain=id==='pn'?400:8;cube.density=id==='pn'?7:4;cube.reference=id==='pn';$('cubeDensity').value=cube.density;$('cubeReference').checked=cube.reference;cube.probeVisible=false;scene.yaw=view==='cube'?-.25:-.35;scene.pitch=view==='cube'?.28:.65;geometryReference=null;renderedKey='';reset();labels();}
function reset(){if(current==='projectile'){pausePlayback(false);time=0;done=false;model=null;return;}cancelDisk();pausePlayback(false);time=0;done=false;reason='';history=[];renderStats=null;if(current==='binary'||current==='pn')model=new Binary(p,current==='pn');else if(current==='schwarzschild')model=new Schwarzschild(p);else model=null;if(current==='schwarzschild')geometryReference=schwarzReference(p.mass,p.r0,p.geometryScaleMode,geometryReference);else if(current==='lens')geometryReference=lensReference(p.mass,p.geometryScaleMode,geometryReference);else if(current==='pn'||!geometryReference)fitGeometry();surfaceY=[p.height||0,0];if(current==='surface'&&p.support==='fall'&&p.height===0){done=true;reason='groundStart';}if(current==='lens'){ray=traceRay(p.impact);otherRays=[-12,-9,-6,3.8,5,5.4,9,12].map(b=>{if(b>=0)return traceRay(b);const r=traceRay(-b);r.path=r.path.map(x=>[x[0],-x[1],x[2]]);return r;});}recordHistory();configureTimeline();syncPlay();update();if(view==='disk')requestDisk();}
function maxTime(){if(current==='binary'||current==='pn')return 60;if(current==='schwarzschild')return 1500;if(current==='jump')return Math.max(...planets.map(b=>jump(b,p.mass,p.earthHeight).flight_s))*1.05;if(current==='surface')return p.support==='fall'?Math.max(2,Math.sqrt(2*p.height/earth.g)*1.3):20;if(current==='clocks')return 30;return 1;}
function modelTime(){return model?(current==='schwarzschild'?model.tau:model.t):time;}
function configureTimeline(){$('timeline').max=maxTime();$('timeline').step=maxTime()/300;}
function recordHistory(){if(current==='surface')history.push({t:time,x:0,z:surfaceY[0]+earth.radius,h:surfaceY[0]});if(current==='jump'){const b=planets.find(b=>b.id===p.planet),j=jump(b,p.mass,p.earthHeight);history.push({t:time,x:Math.max(0,j.v0_ms*time-.5*j.g_ms2*time*time),z:0});}if(history.length>1600)history.shift();}
function advance(amount,budgetMs=Infinity){
 const deadline=performance.now()+budgetMs;
 if(model){const end=modelTime()+amount;let n=0;while(modelTime()<end&&!model.done&&n++<30000&&(n===1||performance.now()<deadline)){model.step(Math.min(current==='schwarzschild'?.15:.006,end-modelTime()));}done=model.done;reason=model.reason;}
 else {const end=Math.min(maxTime(),time+amount);if(current==='surface'&&p.support==='fall'){while(time<end&&!done&&performance.now()<deadline){const h=Math.min(.02,end-time);surfaceY=rk4(surfaceY,h,([z,v])=>[v,-G*earth.mass/(earth.radius+z)**2]);time+=h;if(surfaceY[0]<=0){surfaceY=[0,surfaceY[1]];done=true;reason='impact';}}}else time=end;recordHistory();if(time>=maxTime()-1e-8)done=true;}
 if(modelTime()>=maxTime())done=true;if(done)pausePlayback();
}
function syncPlay(){$('playBtn').disabled=current==='surface'&&p.support==='fall'&&p.height===0;$('playIcon').textContent=running?'Ⅱ':done?'↺':'▶';$('playText').textContent=running?T('pause'):done?T('restart'):modelTime()>0?T('resume'):T('start');$('status').textContent=running?T('running'):done?T('complete'):modelTime()>0?T('paused'):T('ready');$('playBtn').setAttribute('aria-pressed',String(running));$('playBtn').setAttribute('aria-label',running?T('pause'):done?T('restart'):modelTime()>0?T('resume'):T('start'));$('stepBtn').disabled=running||done;if($('playBtn').disabled){$('playIcon').textContent='▶';$('playText').textContent=T('heightRequired');$('playBtn').setAttribute('aria-label',T('heightRequired'));$('status').textContent=T('heightRequired');}}
function heightPreset(){return clockHeights.find(h=>h.id===p.heightPreset)||clockHeights[0];}
function clockRows(){return clockBodies.map(body=>{
 const row=p.mode==='height'?clockAtHeight(body,clockHeightOverrides[body.id]??(clockOverrides[body.id]!==undefined?clockOverrides[body.id]-clockReference(body):heightPreset().height_m),p.duration*DAY,p.observerType):clock(body,clockOverrides[body.id]??(p.mode==='scaled'?p.ratio*rs(body.mass):p.distance*AU),p.duration*DAY,p.observerType);
 return {...row,label:body[lang],color:body.color};
});}

