for(const id of ['newtonNav','grNav'])$(id).addEventListener('click',e=>{const b=e.target.closest('[data-exp]');if(b)select(b.dataset.exp);});
$('params').addEventListener('input',e=>{const el=e.target;if(el.type==='range'){changeParam(el);return;}if(current==='surface'&&el.dataset.key==='height'&&el.value!==''&&Number.isFinite(Number(el.value))&&Number(el.value)>=0&&Number(el.value)<=100000)changeParam(el);});$('params').addEventListener('change',e=>{if(e.target.type==='range')return;changeParam(e.target);});
function changeParam(el){const key=el.dataset.key;if(!key)return;const q=experiments[current].params.find(x=>x.key===key);let value=['select','planet'].includes(q.type)?el.value:Number(el.value);if(typeof value==='number'&&(!Number.isFinite(value)||value<q.min||value>q.max)){el.setCustomValidity(T('invalid'));el.reportValidity();return;}el.setCustomValidity('');p[key]=value;if(['schwarzschild','lens'].includes(current)&&key==='geometryScaleMode'){if(value==='relative')fitGeometry();update();return;}if(q.disk){if(q.type==='range')$('o-'+key).textContent=nf(value,3)+' '+q.units;renderStats=null;cancelDisk();update();$('renderProgress').hidden=false;$('renderProgress').textContent=T('rendering');diskTimer=setTimeout(requestDisk,180);return;}if(key==='object')p.mass={person:50,car:1500,house:1e6,block:2}[value];if(current==='clocks'&&['mode','distance','ratio','heightPreset'].includes(key)){clockOverrides={};clockHeightOverrides={};}if(['object','mode'].includes(key))controls();else if(q.type==='range')$('o-'+key).textContent=nf(value,3)+' '+q.units;reset();}
for(const [id,key] of [['cubeProbeVisible','probeVisible'],['cubeMode','mode'],['cubeDensity','density'],['cubeReference','reference'],['cubeCutaway','cutaway'],['cubeBody','body']])$(id).addEventListener('change',e=>{cube[key]=key==='density'?Number(e.target.value):['body','mode'].includes(key)?e.target.value:e.target.checked;update();});

